<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\HasMany;use Illuminate\Database\Eloquent\SoftDeletes;
final class Party extends Model{use HasUuids,SoftDeletes;protected$fillable=['type','display_name','legal_identity','status'];protected function casts():array{return['legal_identity'=>'array'];}public function contacts():HasMany{return$this->hasMany(PartyContact::class);}public function identifiers():HasMany{return$this->hasMany(PartyIdentifier::class);}public function customers():HasMany{return$this->hasMany(TenantCustomer::class);}public function consents():HasMany{return$this->hasMany(Consent::class);}public function attributions():HasMany{return$this->hasMany(CustomerAttribution::class);}}
